-- 3 AUDIO COM PCALL + FALLBACK
local PunchSound=4979513906 local MoanSounds={9125652466,9125652949,9125652443,9125651079,9125652963}
local SoundIdsList={4590657391,6895079853,6026984224,4979513906,9125652466,9125652949,9125652443,9125651079,9125652963,6895079853}
local SoundTemplates={} local SoundCacheFolder=Instance.new("Folder") SoundCacheFolder.Name="ZHX_SoundCache" pcall(function() SoundCacheFolder.Parent=SoundService end)
task.spawn(function() pcall(function() local insts={} for _,id in ipairs(SoundIdsList) do local ok,s=pcall(function() local snd=Instance.new("Sound") snd.SoundId="rbxassetid://"..tostring(id) snd.Volume=0.5 snd.Parent=SoundCacheFolder return snd end) if ok and s then SoundTemplates[id]=s table.insert(insts,s) end end pcall(function() if ContentProvider then ContentProvider:PreloadAsync(insts) end end) end) end)
local function PlaySound(id,vol,pitch)
 pcall(function()
  local tmpl=SoundTemplates[id] local s
  if tmpl then local ok,cl=pcall(function() return tmpl:Clone() end) s=ok and cl or nil end
  if not s then local ok2,nw=pcall(function() local x=Instance.new("Sound") x.SoundId="rbxassetid://"..tostring(id) return x end) if not ok2 then return end s=nw end
  s.Volume=vol or 0.5 s.PlaybackSpeed=pitch or (0.9+math.random()*0.2) s.Parent=SoundService
  local okPlay=pcall(function() s:Play() end) if not okPlay then pcall(function() s:Destroy() end) return end
  if Debris then Debris:AddItem(s,4) end
 end)
end
local function PlaySoundFallback(primary,fallbacks,vol,pitch)
  if not SoundService then return end
  local ok=false
  pcall(function() PlaySound(primary,vol,pitch) ok=true end)
  if not ok and type(fallbacks)=="table" then for _,fid in ipairs(fallbacks) do if pcall(function() PlaySound(fid,vol,pitch) end) then break end end end
end
local cachedVoice=nil
local function PlayTTS(text) task.spawn(function() pcall(function() if cachedVoice then local s=Instance.new("Sound") s.SoundId=cachedVoice s.Volume=1 s.Parent=SoundService s:Play() Debris:AddItem(s,10) return end if not requestFunc then PlaySoundFallback(4590657391,{6895079853},1) return end local resp=requestFunc({Url="https://streamlabs.com/polly/speak",Method="POST",Headers={["Content-Type"]="application/json"},Body=HttpService:JSONEncode({voice="Joanna",text=text})}) if resp and resp.Body then local ok,data=pcall(function() return HttpService:JSONDecode(resp.Body) end) if ok and data and data.speak_url then cachedVoice=data.speak_url local s=Instance.new("Sound") s.SoundId=data.speak_url s.Volume=1 s.Parent=SoundService s:Play() Debris:AddItem(s,10) end end end) end) end

