-- 5 CLOUD + JOIN FEED
local API="https://api.zhxhub.com/v1"
local ServerActiveUsers={} local CloudJoins={} -- {username,displayName,userId,role,jobId,placeId,time,serverLabel}
local function PushCloudJoin(entry) table.insert(CloudJoins,1,entry) if #CloudJoins>30 then table.remove(CloudJoins,#CloudJoins) end end
local function PerformCloudHandshake() if not requestFunc then return end task.spawn(function() pcall(function() requestFunc({Url=API.."/handshake",Method="POST",Headers={["Content-Type"]="application/json"},Body=HttpService:JSONEncode({userId=LP.UserId,username=LP.Name,displayName=LP.DisplayName,jobId=game.JobId,placeId=game.PlaceId,timestamp=os.time()})}) end) end) end
local function PollCloud()
 if not requestFunc then return end
 pcall(function()
  local resp=requestFunc({Url=API.."/users?jobId="..tostring(game.JobId),Method="GET"})
  if resp and resp.Body then local ok,data=pcall(function() return HttpService:JSONDecode(resp.Body) end) if ok and type(data)=="table" then
   if data.users and type(data.users)=="table" then local m={} for _,uid in ipairs(data.users) do if tonumber(uid) then m[tonumber(uid)]=true end end ServerActiveUsers=m end
   if data.joins and type(data.joins)=="table" then for _,j in ipairs(data.joins) do local exists=false for _,e in ipairs(CloudJoins) do if e.userId==tonumber(j.userId) and e.jobId==tostring(j.jobId) then exists=true break end end if not exists then PushCloudJoin({username=tostring(j.username or "?"),displayName=tostring(j.displayName or j.username or "?"),userId=tonumber(j.userId) or 0,role=tostring(j.role or "ZHX USER"),jobId=tostring(j.jobId or ""),placeId=tonumber(j.placeId) or game.PlaceId,time=tonumber(j.timestamp) or os.time(),serverLabel="Outro Server"}) end end end
  end end
 end)
end
task.spawn(function() PerformCloudHandshake() while IsScriptRunning do PollCloud() task.wait(3.5) end end)

-- 6 IDENTIFICACAO + MUTUA
local SCRIPT_VERSION="ZHX_v3.0" local SCRIPT_SIGNATURE="ZHX_HUB_ACTIVE_"..SCRIPT_VERSION
local function MarkSelf() pcall(function() LP:SetAttribute("ZHX_ScriptUser",true) LP:SetAttribute("ZHX_Version",SCRIPT_VERSION) LP:SetAttribute("ZHX_Signature",SCRIPT_SIGNATURE) LP:SetAttribute("ZHX_ActiveTime",os.time()) end) pcall(function() local ch=LP.Character if ch then ch:SetAttribute("ZHX_ScriptUser",true) ch:SetAttribute("ZHX_Signature",SCRIPT_SIGNATURE) local hrp=ch:FindFirstChild("HumanoidRootPart") if hrp then hrp:SetAttribute("ZHX_ScriptUser",true) hrp:SetAttribute("ZHX_Signature",SCRIPT_SIGNATURE) if not hrp:FindFirstChild("ZHX_Marker") then local m=Instance.new("StringValue") m.Name="ZHX_Marker" m.Value=SCRIPT_SIGNATURE m.Parent=hrp end end end end) end
if IsScriptRunning then MarkSelf() end
pcall(function() TrackConn(LP.CharacterAdded:Connect(function() task.wait(0.5) if IsScriptRunning then MarkSelf() end end)) end)
local function IsScriptUser(p) if not p then return false end if ServerActiveUsers[p.UserId]==true then return true end local d=false pcall(function() if p:GetAttribute("ZHX_ScriptUser")==true then d=true end if p:GetAttribute("ZHX_Signature")==SCRIPT_SIGNATURE then d=true end end) if d then return true end pcall(function() local ch=p.Character if ch then if ch:GetAttribute("ZHX_ScriptUser")==true then d=true end if ch:GetAttribute("ZHX_Signature")==SCRIPT_SIGNATURE then d=true end local hrp=ch:FindFirstChild("HumanoidRootPart") if hrp then if hrp:GetAttribute("ZHX_ScriptUser")==true then d=true end if hrp:GetAttribute("ZHX_Signature")==SCRIPT_SIGNATURE then d=true end local mk=hrp:FindFirstChild("ZHX_Marker") if mk and mk:IsA("StringValue") and mk.Value==SCRIPT_SIGNATURE then d=true end end end end) return d end
