local SpecialUsers={["danieo_306"]="Official Dev",["xdzinpro11"]="Official Dev",["padella"]="Official Dev",["zn"]="Official Dev",["toehackfazol24"]="Owner",["rafael_1870"]="Owner",["dj_tadala53"]="Owner",["uriel_xter"]="Owner",["lucas20_ss"]="Owner"}
local Blacklist={}
local TagConfig={Enabled=true,ShowSelf=false,ShowOthers=true,MaxDistance=200}
local function HasSpecialInServer() for _,p in ipairs(Players:GetPlayers()) do local n=p.Name:lower() for name,role in pairs(SpecialUsers) do if n==name and role=="Owner" then return true end end end return false end
local ActiveTags={}
local function GetTagRole(p) local n=p.Name:lower() for name,role in pairs(SpecialUsers) do if n==name then return role end end if Blacklist[n] then return "Blacklist" end if IsScriptUser(p) then if HasSpecialInServer() then return "Found Owner" end return "Script User" end return nil end
local function RemoveHeadTag(p) pcall(function() if ActiveTags[p] then pcall(function() ActiveTags[p]:Destroy() end) ActiveTags[p]=nil end local ch=p.Character if ch then for _,cont in ipairs({ch,ch:FindFirstChild("Head"),ch:FindFirstChild("HumanoidRootPart")}) do if cont then for _,v in ipairs(cont:GetChildren()) do if string.sub(v.Name,1,4)=="ZHX_" and v.Name~="ZHX_Marker" then pcall(function() v:Destroy() end) end end end end end end) end

-- TAG ESTILO AK ADMIN - pill preta, losango verde, ZHX em cima, @user embaixo
local function CreateHeadTag(player)
 pcall(function()
  RemoveHeadTag(player)
  if not TagConfig.Enabled then return end
  if player==LP and not TagConfig.ShowSelf then return end -- NUNCA mostra pra si mesmo
  if player~=LP and not TagConfig.ShowOthers then return end
  local role=GetTagRole(player) if not role then return end
  local char=player.Character if not char then return end local head=char:FindFirstChild("Head") if not head then return end
  -- AK: se o player nao tem script e nao e especial, nao cria (mutuo)
  if not IsScriptUser(player) and not SpecialUsers[player.Name:lower()] then return end
  local isSpecial=(role=="Owner" or role=="Found Owner" or role=="Official Dev")
  local badge="ZHX USER" if role=="Official Dev" then badge="ZHX DEV" elseif role=="Owner" then badge="ZHX OWNER" elseif role=="Found Owner" then badge="ZHX FOUND OWNER" elseif role=="Blacklist" then badge="ZHX BLACKLIST" end
  local w=150 if #player.Name>12 then w=170 end if isSpecial then w=w+20 end
  local bb=Instance.new("BillboardGui") bb.Name="ZHX_HeadTag" bb.Adornee=head bb.Size=UDim2.new(0,w,0,38) bb.StudsOffset=Vector3.new(0,2.8,0) bb.AlwaysOnTop=true bb.MaxDistance=isSpecial and 300 or TagConfig.MaxDistance bb.LightInfluence=0 bb:SetAttribute("ZHX_Role",role) bb.Parent=head
  local pill=Instance.new("Frame",bb) pill.Size=UDim2.fromScale(1,1) pill.Position=UDim2.fromScale(0.5,0.5) pill.AnchorPoint=Vector2.new(0.5,0.5) pill.BackgroundColor3=Color3.fromRGB(0,0,0) pill.BackgroundTransparency=0.12 Rnd(pill,UDim.new(0,10))
  local st=Instance.new("UIStroke",pill) st.Thickness=1.2 st.Color=Color3.fromRGB(255,255,255) st.Transparency=0.15
  -- losango verde AK
  local diamond=Instance.new("Frame",pill) diamond.Size=UDim2.new(0,13,0,13) diamond.Position=UDim2.new(0,10,0.5,-6.5) diamond.BackgroundColor3=C.Green diamond.BorderSizePixel=0 diamond.Rotation=45 Rnd(diamond,UDim.new(0,2))
  local glow=Instance.new("UIStroke",diamond) glow.Color=C.Green glow.Thickness=1 glow.Transparency=0.3
  local line=Instance.new("Frame",pill) line.Size=UDim2.new(0,1,0.62,0) line.Position=UDim2.new(0,31,0.5,0) line.AnchorPoint=Vector2.new(0,0.5) line.BackgroundColor3=Color3.fromRGB(255,255,255) line.BackgroundTransparency=0.35 line.BorderSizePixel=0
  local top=Instance.new("TextLabel",pill) top.Size=UDim2.new(1,-42,0,15) top.Position=UDim2.new(0,38,0,3) top.BackgroundTransparency=1 top.Text=badge top.TextColor3=Color3.new(1,1,1) top.Font=Enum.Font.GothamBlack top.TextSize=10 top.TextXAlignment=Enum.TextXAlignment.Left
  local bot=Instance.new("TextLabel",pill) bot.Size=UDim2.new(1,-42,0,13) bot.Position=UDim2.new(0,38,0,18) bot.BackgroundTransparency=1 bot.Text="@"..player.Name bot.TextColor3=Color3.fromRGB(180,180,180) bot.Font=Enum.Font.GothamBold bot.TextSize=9 bot.TextXAlignment=Enum.TextXAlignment.Left bot.TextTruncate=Enum.TextTruncate.AtEnd
  ActiveTags[player]=bb
 end)
end
local function ApplyAllTags() for _,p in ipairs(Players:GetPlayers()) do if IsScriptRunning and TagConfig.Enabled then CreateHeadTag(p) else RemoveHeadTag(p) end end end
local function RemoveAllTags() for _,p in ipairs(Players:GetPlayers()) do RemoveHeadTag(p) end end
task.spawn(function() while IsScriptRunning do task.wait(1.2) if IsScriptRunning and TagConfig.Enabled then for _,p in ipairs(Players:GetPlayers()) do if IsScriptRunning then pcall(function() local role=GetTagRole(p) local ch=p.Character local head=ch and ch:FindFirstChild("Head") local ex=head and head:FindFirstChild("ZHX_HeadTag") if role then if not ex then CreateHeadTag(p) elseif ex:GetAttribute("ZHX_Role")~=role then ex:Destroy() CreateHeadTag(p) end elseif ex then ex:Destroy() end end) end end end end end)
local function HookPlayerTags(p) pcall(function() TrackConn(p.CharacterAdded:Connect(function() task.wait(1) if IsScriptRunning and TagConfig.Enabled then CreateHeadTag(p) end end)) TrackConn(p:GetAttributeChangedSignal("ZHX_ScriptUser"):Connect(function() if IsScriptRunning and TagConfig.Enabled then task.wait(0.3) CreateHeadTag(p) end end)) TrackConn(p:GetAttributeChangedSignal("ZHX_Signature"):Connect(function() if IsScriptRunning and TagConfig.Enabled then task.wait(0.3) CreateHeadTag(p) end end)) end) end
for _,p in ipairs(Players:GetPlayers()) do HookPlayerTags(p) end
pcall(function() TrackConn(Players.PlayerAdded:Connect(function(p) HookPlayerTags(p) -- JOIN FEED LOCAL: alguem entrou no MEU server com ZHX? detecta 1s depois
 task.spawn(function() task.wait(1.2) if IsScriptRunning and IsScriptUser(p) then local role=GetTagRole(p) or "ZHX USER" PushCloudJoin({username=p.Name,displayName=p.DisplayName,userId=p.UserId,role=role,jobId=game.JobId,placeId=game.PlaceId,time=os.time(),serverLabel="Neste Server"}) PlaySoundFallback(SFX.Notify,{SFX.Success},0.4) end end) end)) TrackConn(Players.PlayerRemoving:Connect(RemoveHeadTag)) end)
task.spawn(function() task.wait(0.4) if IsScriptRunning and TagConfig.Enabled then ApplyAllTags() end end)

-- 7 REMOTES / OUTFIT / RAGDOLL (mantido do v3, com pcall)
local RemoteCache={} local function GetRemote(name) if RemoteCache[name] then return RemoteCache[name] end local ok,res=pcall(function() for _,v in ipairs(RS and RS:GetDescendants() or {}) do if v.Name==name then return v end end return nil end) if ok and res then RemoteCache[name]=res return res end return nil end
local function InvokeCatalogRemote(payload) local r=GetRemote("CatalogGuiRemote") if not r then local ev=RS and RS:FindFirstChild("Events") if ev then r=ev:FindFirstChild("CatalogGuiRemote") end end if not r then return false,"Remote not found" end local ok,err=pcall(function() r:InvokeServer(payload) end) if ok then return true end return false,tostring(err) end
local function ConvertDescription(desc) local ok,dict=pcall(function() local cm=GetRemote("CatalogModule") if cm then local M=require(cm) if M and M.ToDictionary then return M:ToDictionary(desc) end end end) if ok and dict then return dict end return desc end
local State={ViewingPlayer=nil}
local Ragdoll={On=false} function Ragdoll:Set(en) self.On=en pcall(function() local h=LP.Character and LP.Character:FindFirstChildOfClass("Humanoid") if not h then return end if self.On then h:SetStateEnabled(Enum.HumanoidStateType.GettingUp,false) h:ChangeState(Enum.HumanoidStateType.Physics) else h:SetStateEnabled(Enum.HumanoidStateType.GettingUp,true) h:ChangeState(Enum.HumanoidStateType.GettingUp) end end) if self.On then PlaySoundFallback(PunchSound,{6895079853},1,math.random(95,115)/100) end return self.On end function Ragdoll:Toggle() return self:Set(not self.On) end
pcall(function() TrackConn(RunService.PreSimulation:Connect(function() if not IsScriptRunning or not Ragdoll.On then return end pcall(function() local h=LP.Character and LP.Character:FindFirstChildOfClass("Humanoid") if not h or h:GetState()==Enum.HumanoidStateType.Dead then return end h:ChangeState(Enum.HumanoidStateType.Physics) h.Jump=false end) end)) end)
local ragFalling,ragLastLand=false,0 pcall(function() TrackConn(RunService.Heartbeat:Connect(function() if not IsScriptRunning or not Ragdoll.On then ragFalling=false return end pcall(function() local ch=LP.Character if not ch then return end local root=ch:FindFirstChild("HumanoidRootPart") if not root then return end local vy=root.AssemblyLinearVelocity.Y if vy<-2.5 then ragFalling=true end if ragFalling and vy>-1 then ragFalling=false if os.clock()-ragLastLand>0.8 then ragLastLand=os.clock() PlaySoundFallback(PunchSound,{6895079853},1,math.random(85,115)/100) PlaySoundFallback(MoanSounds[math.random(1,#MoanSounds)],{9125652466},0.8,math.random(90,120)/100) end end end) end)) end)
local function ClearAllClothing(hum) if not hum then return end local ch=hum.Parent if not ch then return end pcall(function() for _,v in ipairs(ch:GetChildren()) do if v:IsA("Shirt") or v:IsA("Pants") or v:IsA("ShirtGraphic") then v:Destroy() end end for _,acc in ipairs(hum:GetAccessories()) do pcall(function() acc:Destroy() end) end for _,v in ipairs(ch:GetDescendants()) do if v:GetAttribute("ZHX") then pcall(function() v:Destroy() end) end end end) end
local function ApplyDescriptionSafe(hum,desc) if not hum or not desc then return false end local suc=false local ok,rok=pcall(function() local dict=ConvertDescription(desc) return InvokeCatalogRemote({Action="CreateAndWearHumanoidDescription",Properties=dict,RigType=hum.RigType}) end) if ok and rok==true then suc=true end if not suc then suc=pcall(function() hum:ApplyDescription(desc) end) end return suc end
local function CloneAllAccessories(tc,lh) if not tc or not lh then return 0,0 end local cp,fl=0,0 pcall(function() for _,v in ipairs(tc:GetChildren()) do if v:IsA("Accessory") then local ex=false for _,e in ipairs(lh:GetAccessories()) do if e.Name==v.Name then ex=true break end end if not ex then local cl=v:Clone() cl:SetAttribute("ZHX",true) local h=cl:FindFirstChild("Handle") if h then h.Anchored=false h.CanCollide=false h.Massless=true for _,j in ipairs(h:GetChildren()) do if j:IsA("Weld") or j:IsA("WeldConstraint") or j:IsA("Motor6D") or j:IsA("Snap") then j:Destroy() end end end local okA=pcall(function() lh:AddAccessory(cl) end) if not okA then task.wait(0.06) okA=pcall(function() lh:AddAccessory(cl) end) end if okA then cp=cp+1 else fl=fl+1 pcall(function() cl:Destroy() end) end end end end end) return cp,fl end
local function CopyOutfit(t,st) if not IsScriptRunning then return end local tc,lc=t.Character,LP.Character if not tc or not lc then st("Error: no character") return end local th=tc:FindFirstChildOfClass("Humanoid") local lh=lc:FindFirstChildOfClass("Humanoid") if not th or not lh then st("Error: no humanoid") return end st("Copying full outfit...") PlaySoundFallback(SFX.Click,{SFX.Notify},0.5) ClearAllClothing(lh) task.wait(0.25) local okTd,td=pcall(function() return th:GetAppliedDescription() end) if okTd and td then ApplyDescriptionSafe(lh,td:Clone()) end task.wait(0.5) st("Copying accessories...") local copied=CloneAllAccessories(tc,lh) task.wait(0.15) pcall(function() local tH,lH=tc:FindFirstChild("Head"),lc:FindFirstChild("Head") if tH and lH then local tf=tH:FindFirstChildOfClass("Decal") local lf=lH:FindFirstChildOfClass("Decal") if tf then if not lf then lf=Instance.new("Decal") lf.Name="face" lf.Parent=lH end if not lf:GetAttribute("ZHX_OG") then lf:SetAttribute("ZHX_OG",lf.Texture) end lf.Texture=tf.Texture end end end) pcall(function() local tbc=tc:FindFirstChildOfClass("BodyColors") local lbc=lc:FindFirstChildOfClass("BodyColors") if tbc and lbc then lbc.HeadColor3=tbc.HeadColor3 lbc.TorsoColor3=tbc.TorsoColor3 lbc.LeftArmColor3=tbc.LeftArmColor3 lbc.RightArmColor3=tbc.RightArmColor3 lbc.LeftLegColor3=tbc.LeftLegColor3 lbc.RightLegColor3=tbc.RightLegColor3 end end) PlaySoundFallback(SFX.Success,{SFX.Notify},0.6) st("Outfit copied! ("..copied.." accessories)") end
local function CopyOriginalOutfit(target,st) st=st or function() end if not IsScriptRunning then return end if not target then st("Invalid target") return end local tc=target.Character local lc=LP.Character if not lc then st("No character") return end local lh=lc:FindFirstChildOfClass("Humanoid") if not lh then st("Error: no humanoid") return end st("Clearing...") PlaySoundFallback(SFX.Click,{SFX.Notify},0.5) ClearAllClothing(lh) task.wait(0.25) st("Loading original...") local desc=nil local ok1,d1=pcall(function() return Players:GetHumanoidDescriptionFromUserId(target.UserId) end) if ok1 and d1 then desc=d1 elseif tc then local th=tc:FindFirstChildOfClass("Humanoid") if th then local ok2,d2=pcall(function() return th:GetAppliedDescription() end) if ok2 and d2 then desc=d2 end end end if not desc then st("Failed to load") return end local applied=false pcall(function() local dict=ConvertDescription(desc) applied=InvokeCatalogRemote({Action="CreateAndWearHumanoidDescription",Properties=dict,RigType=lh.RigType}) end) if not applied then pcall(function() lh:ApplyDescription(desc) end) end task.wait(0.5) if tc then local copied,failed=CloneAllAccessories(tc,lh) st("Accessories: "..copied.." copied"..(failed>0 and (", "..failed.." failed") or "")) end PlaySoundFallback(SFX.Success,{SFX.Notify},0.6) task.wait(0.3) st("Original outfit copied!") end
local function ResetOutfit(st) st=st or function() end if not IsScriptRunning then return end local lc=LP.Character if not lc then st("No character") return end local lh=lc:FindFirstChildOfClass("Humanoid") if not lh then st("No humanoid") return end st("Resetting...") PlaySoundFallback(SFX.Click,{SFX.Notify},0.5) pcall(function() local lH=lc:FindFirstChild("Head") if lH then local lf=lH:FindFirstChildOfClass("Decal") if lf and lf:GetAttribute("ZHX_OG") then lf.Texture=lf:GetAttribute("ZHX_OG") lf:SetAttribute("ZHX_OG",nil) end end end) ClearAllClothing(lh) task.wait(0.25) local ok,dd=pcall(function() return Players:GetHumanoidDescriptionFromUserId(LP.UserId) end) if not ok or not dd then st("Failed") return end local applied=false pcall(function() local dict=ConvertDescription(dd) applied=InvokeCatalogRemote({Action="CreateAndWearHumanoidDescription",Properties=dict,RigType=lh.RigType}) end) if not applied then pcall(function() lh:ApplyDescription(dd) end) end task.wait(0.4) PlaySoundFallback(SFX.Success,{SFX.Notify},0.6) st("Outfit reset!") end
local function FindPlayerByName(q) q=string.lower(q or "") if q=="" then return nil end for _,p in ipairs(Players:GetPlayers()) do if string.lower(p.Name):find(q,1,true) or string.lower(p.DisplayName):find(q,1,true) then return p end end return nil end
local function GotoPlayerInstant(t) if not IsScriptRunning or not t then return false end local lc=LP.Character local tc=t.Character if not lc or not tc then return false end local lR=lc:FindFirstChild("HumanoidRootPart") or lc:FindFirstChild("Torso") local tR=tc:FindFirstChild("HumanoidRootPart") or tc:FindFirstChild("Torso") if not lR or not tR then return false end pcall(function() local dest=tR.CFrame*CFrame.new(0,0,4) lc:PivotTo(dest) lR.CFrame=dest lR.AssemblyLinearVelocity=Vector3.zero lR.AssemblyAngularVelocity=Vector3.zero end) PlaySoundFallback(SFX.Success,{SFX.Notify},0.5) return true end
local function GetStatus(p) local s="None" pcall(function() if not p or not p.Character then return end local a=p:GetAttribute("OverheadStatusOnVisible") or p:GetAttribute("Status") if a and a~="" then s=a return end local h=p.Character:FindFirstChild("Head") if h then for _,v in ipairs(h:GetChildren()) do if v:IsA("BillboardGui") and v.Name~="ZHX_HeadTag" then local l=v:FindFirstChildWhichIsA("TextLabel") if l and l.Text~="" then s=l.Text return end end end end end) return s end
local function AddCommas(n) local ok,res=pcall(function() local NU=require(RS:WaitForChild("Modules",2) and RS.Modules:WaitForChild("Util",2) and RS.Modules.Util:WaitForChild("NumbersUtil",2)) if NU and NU.addComas then return NU:addComas(n) end end) if ok and res then return tostring(res) end local s=tostring(math.floor(tonumber(n) or 0)) local k while true do s,k=string.gsub(s,"^(-?%d+)(%d%d%d)","%1,%2") if k==0 then break end end return s end
local function GetPlayerLikes(p) local n=0 pcall(function() n=tonumber(p and p:GetAttribute("Likes")) or 0 end) return n end
local function PlayHeartAnim() pcall(function() local pg=LP:FindFirstChild("PlayerGui") local vp=pg and pg:FindFirstChild("ViewPlayer") local tmpl=vp and vp:FindFirstChild("ScriptTemplates") and vp.ScriptTemplates:FindFirstChild("LikeAnimImage") local sendLike=vp and vp:FindFirstChild("Main") and vp.Main:FindFirstChild("Menu") and vp.Main.Menu:FindFirstChild("Likes") and vp.Main.Menu.Likes:FindFirstChild("SendLike") if tmpl and sendLike then local cl=tmpl:Clone() cl.Size=UDim2.fromOffset(sendLike.AbsoluteSize.X,sendLike.AbsoluteSize.Y) cl.AnchorPoint=Vector2.new(0.5,0.5) cl.Position=UDim2.fromOffset(sendLike.AbsolutePosition.X+sendLike.AbsoluteSize.X/2,sendLike.AbsolutePosition.Y+sendLike.AbsoluteSize.Y/2) cl.Parent=vp TweenService:Create(cl,TweenInfo.new(0.35,Enum.EasingStyle.Cubic,Enum.EasingDirection.Out,0,true,0),{Size=UDim2.fromOffset(sendLike.AbsoluteSize.X*2.5,sendLike.AbsoluteSize.Y*2.5),ImageColor3=Color3.fromRGB(255,255,255)}):Play() Debris:AddItem(cl,1) return end error("no template") end) end
local function FirePopup(msg) pcall(function() local r=GetRemote("ClientPopupMessage") if r then r:Fire(msg) end end) end

-- 8 CHAT CMDS
local function ProcessCommand(msg) if not IsScriptRunning or not msg or string.sub(msg,1,1)~="-" then return end local parts=string.split(string.sub(msg,2)," ") local cmd=string.lower(parts[1] or "") local ta=parts[2] or "" if cmd=="cp" then local t=FindPlayerByName(ta) if t then CopyOutfit(t,function() end) end elseif cmd=="cp2" then local t=FindPlayerByName(ta) if t then CopyOriginalOutfit(t,function() end) end elseif cmd=="tp" then local t=FindPlayerByName(ta) if t then GotoPlayerInstant(t) end elseif cmd=="vw" then local t=FindPlayerByName(ta) if t and t.Character and t.Character:FindFirstChildOfClass("Humanoid") then workspace.CurrentCamera.CameraSubject=t.Character:FindFirstChildOfClass("Humanoid") State.ViewingPlayer=t end elseif cmd=="uv" then if LP.Character and LP.Character:FindFirstChildOfClass("Humanoid") then workspace.CurrentCamera.CameraSubject=LP.Character:FindFirstChildOfClass("Humanoid") State.ViewingPlayer=nil end elseif cmd=="rd" then Ragdoll:Toggle() elseif cmd=="ca" then pcall(function() StarterGui:SetCore("ChatMakeSystemMessage",{Text="[ZHX HUB] Commands: -cp -cp2 -tp -vw -uv -rd -ca",Color=C.Accent}) end) end end
local chatModern=false if TextChatService then local ok,ver=pcall(function() return TextChatService.ChatVersion end) if ok and ver==Enum.ChatVersion.TextChatService then chatModern=true pcall(function() TrackConn(TextChatService.MessageReceived:Connect(function(m) if IsScriptRunning and m.TextSource and m.TextSource.UserId==LP.UserId then ProcessCommand(m.Text) end end)) end) end end if not chatModern then pcall(function() TrackConn(LP.Chatted:Connect(function(m) if IsScriptRunning then ProcessCommand(m) end end)) end) end

