do local UScroll=Instance.new("ScrollingFrame",TabUpd) UScroll.Size=UDim2.new(1,-20,1,-16) UScroll.Position=UDim2.new(0,10,0,8) UScroll.BackgroundTransparency=1 UScroll.AutomaticCanvasSize=Enum.AutomaticSize.Y UScroll.ScrollBarThickness=3 UScroll.ScrollBarImageColor3=C.Dim local ULay=Instance.new("UIListLayout",UScroll) ULay.Padding=UDim.new(0,8) ULay.HorizontalAlignment=Enum.HorizontalAlignment.Center local function MkUpd(title,sub,items,hl)
  local list={}
  if type(items)=="table" then list=items elseif type(items)=="string" then list={items} elseif items~=nil then list={tostring(items)} end
  if type(hl)=="string" then table.insert(list,hl) hl=false end
  if type(hl)~="boolean" then hl=false end
  local h=34+14+(#list*18)+10
  local F=Instance.new("Frame",UScroll)
  F.Size=UDim2.new(1,-2,0,h) F.BackgroundColor3=C.Card Rnd(F,UDim.new(0,6)) Stk(F,hl and C.BorderBright or C.Border,hl and 1.5 or 1)
  local T=Instance.new("TextLabel",F) T.Size=UDim2.new(1,-16,0,18) T.Position=UDim2.new(0,10,0,8) T.BackgroundTransparency=1 T.Text=tostring(title or "") T.TextColor3=C.Txt T.Font=Enum.Font.GothamBlack T.TextSize=Fs T.TextXAlignment=Enum.TextXAlignment.Left
  local S=Instance.new("TextLabel",F) S.Size=UDim2.new(1,-16,0,13) S.Position=UDim2.new(0,10,0,26) S.BackgroundTransparency=1 S.Text=tostring(sub or "") S.TextColor3=C.Dim S.Font=Enum.Font.Gotham S.TextSize=Fs-2 S.TextXAlignment=Enum.TextXAlignment.Left
  for i,item in ipairs(list) do local L=Instance.new("TextLabel",F) L.Size=UDim2.new(1,-20,0,16) L.Position=UDim2.new(0,12,0,42+(i-1)*18) L.BackgroundTransparency=1 L.Text="• "..tostring(item) L.TextColor3=Color3.fromRGB(210,210,210) L.Font=Enum.Font.Gotham L.TextSize=Fs-1 L.TextXAlignment=Enum.TextXAlignment.Left L.TextTruncate=Enum.TextTruncate.AtEnd end
  return F end MkUpd("v3.0 - ZHX TAG EDITION","Tag Nova",{"Loading de 6 segundos com %"},true) MkUpd("O que foi adicionado?","Leia isso",{"Likes view, dar like no alvo, Reset me, Emotes."},false) end
