local function SendLikeToTarget(target,st) if not IsScriptRunning or not target then return end st=st or function() end local sent=false pcall(function() local r=GetRemote("LikeOutfit") if not r then local ev=RS and RS:FindFirstChild("Events") if ev then r=ev:FindFirstChild("LikeOutfit") end end if r then r:FireServer(target) sent=true end end) if sent then PlaySoundFallback(SFX.Success,{SFX.Notify},0.5) PlayHeartAnim() st("Like enviado para @"..target.Name.."!") LkLbl.Text="Likes: "..AddCommas(GetPlayerLikes(target)+1) task.delay(0,function() if IsScriptRunning then UpdLikes() end end) else st("Remote LikeOutfit não encontrado") PlaySoundFallback(SFX.Click,{SFX.Notify},0.4) end end
