local function ReportSkin(target,st) if not IsScriptRunning or not target then return end st=st or function() end st("Preparando report...") local reason=nil local promptOk=pcall(function() local pr=GetRemote("ClientPromptTextInput") if pr then reason=pr:Invoke({PromptText="Reportar Skin de @"..target.Name,PlaceholderText="Motivo do report (opcional)...",AllowEmptyText=true,MaxCharacters=255,FootnoteText="Reports falsos podem ter consequências.",FrameSize=UDim2.fromScale(0.4,0.4),FramePosition=UDim2.fromScale(0.5,0.5)}) end end) if promptOk and reason==nil then st("Report cancelado.") FirePopup("Your report has been cancelled.") return end if not promptOk then reason="Inappropriate outfit/skin" end if reason=="" then reason="Inappropriate outfit/skin" end local confirmed=true pcall(function() local yn=GetRemote("ClientPromptYesNoInput") if yn then confirmed=yn:Invoke({PromptText="Confirmar report da skin de @"..target.Name.."?"}) if confirmed==nil then confirmed=true end end end) if not confirmed then st("Report cancelado.") FirePopup("Your report has been cancelled.") return end local okInv,res=pcall(function() local r=GetRemote("PlayerReportSystemRemoteFunction") if not r then local ev=RS and RS:FindFirstChild("Events") if ev then r=ev:FindFirstChild("PlayerReportSystemRemoteFunction") end end if r then return r:InvokeServer({Action="ReportPlayer",Target=target,Category="Other",AdditionalInfo=reason}) end return nil end) if okInv then if res and res.Message then local prefix=res.Success and "[Success]: " or "[Error]: " FirePopup(prefix..tostring(res.Message)) else FirePopup("[Success]: Report enviado.") end PlaySoundFallback(SFX.Success,{SFX.Notify},0.5) st("Skin de @"..target.Name.." reportada!") else st("Falha ao enviar report") PlaySoundFallback(SFX.Click,{SFX.Notify},0.4) end end
local RepBtn=MkUniformBtn("Reportar Skin",AA) RepBtn.Activated:Connect(function() if not IsScriptRunning then return end if not Sel then STxt.Text="Select a player!" return end PlaySoundFallback(SFX.Click,{SFX.Notify},0.4) task.spawn(function() ReportSkin(Sel,function(m) STxt.Text=m end) end) end)
